def get_authorization_data(client, code_verifier: str, organization:
    Optional[Organization]=None, sign_up: bool=False, ensure_auth: bool=
    False, headless: bool=False) ->Tuple[str, str]:
    kwargs = {
        'sign_up': sign_up,
        'locale': 'en',
        'ensure_auth': ensure_auth,
        'headless': headless
    }

    if organization is not None:
        kwargs['organization'] = organization.id

    authorization_url = client.create_authorization_url(CLI_AUTH, code_verifier=code_verifier, **kwargs)
    return authorization_url, code_verifier
